#!/usr/bin/env python3
"""
Academic Writer — AI Typography Detector / Fixer (CLI)

Deterministic (non-LLM) pass over a paragraph of text that scrubs the
mechanical typography tells left behind by LLM generation: em/en-dashes used
as parenthetical breaks, curly/straight quote mismatches across script
direction, RTL punctuation-order mistakes in Hebrew, and stray Unicode
directional-formatting characters.

This script never touches content, wording, or citations — it only fixes
typography. Content-level "Anti-AI" scoring (Tier 2) is a separate, LLM-driven
step described in src/skills/write/references/anti-ai-patterns-*.md.

Usage (matches the calling convention used by section-writer.md):

    echo "$PARAGRAPH_TEXT" | python3 detect-ai-typography.py --fix-and-output --json

Reads text from stdin by default, or from --input FILE.
Always exits 0 and prints a single JSON object to stdout, even when there
are zero fixes:

    {
      "fixed_text": "...",
      "fixes": [
        {"type": "em_dash", "original": "—", "replacement": "-", "position": 42},
        ...
      ]
    }

Flags:
    --fix-and-output    Apply fixes and return the fixed text (default mode;
                         the only mode currently used by callers). Without
                         this flag the script runs detect-only: fixes are
                         still reported but fixed_text equals the input.
    --json               Emit JSON (currently the only supported output
                         format; kept explicit for forward compatibility).
    --input FILE         Read text from FILE instead of stdin.
    --dash-replacement {hyphen,comma,colon,remove}
                         Convention used to fix em-dashes and non-numeric-
                         range en-dashes. Defaults to
                         thresholds.json > typography.dashReplacement (falls
                         back to "hyphen" if thresholds.json is unreadable).
    --no-dashes, --no-quotes, --no-rtl-punctuation, --no-directional-marks
                         Disable individual fix categories.

No third-party dependencies — Python 3 standard library only.
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Optional

sys.path.insert(0, str(Path(__file__).resolve().parent / "lib"))

from typography_fixes import (  # noqa: E402
    DASH_REPLACEMENTS,
    load_default_dash_replacement,
    run as run_fixes,
)


def build_arg_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Deterministic AI-typography detector/fixer for academic prose."
    )
    parser.add_argument(
        "--input", type=str, default=None, help="Read text from FILE instead of stdin."
    )
    parser.add_argument(
        "--fix-and-output",
        action="store_true",
        help="Apply fixes and return fixed_text (default behavior of this script).",
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="Emit JSON output (currently the only supported format).",
    )
    parser.add_argument(
        "--dash-replacement",
        choices=sorted(DASH_REPLACEMENTS.keys()),
        default=None,
        help="Override the em/en-dash fix convention (default: thresholds.json > typography.dashReplacement).",
    )
    parser.add_argument("--no-dashes", action="store_true", help="Disable dash fixes.")
    parser.add_argument(
        "--no-quotes", action="store_true", help="Disable quote normalization."
    )
    parser.add_argument(
        "--no-rtl-punctuation",
        action="store_true",
        help="Disable RTL punctuation-order fixes.",
    )
    parser.add_argument(
        "--no-directional-marks",
        action="store_true",
        help="Disable directional-mark stripping.",
    )
    return parser


def main(argv: Optional[list[str]] = None) -> int:
    parser = build_arg_parser()
    args = parser.parse_args(argv)

    if args.input:
        text = Path(args.input).read_text(encoding="utf-8")
    else:
        text = sys.stdin.read()

    # Strip exactly one trailing newline introduced by `echo`, preserving any
    # meaningful internal newlines/whitespace in the paragraph itself.
    if text.endswith("\n"):
        text = text[:-1]

    script_dir = Path(__file__).resolve().parent
    dash_replacement = args.dash_replacement or load_default_dash_replacement(
        script_dir
    )

    report = run_fixes(
        text,
        dash_replacement=dash_replacement,
        do_dashes=not args.no_dashes,
        do_quotes=not args.no_quotes,
        do_rtl=not args.no_rtl_punctuation,
        do_directional=not args.no_directional_marks,
    )

    if not args.fix_and_output:
        # Detect-only mode: report fixes but do not apply them.
        report = {"fixed_text": text, "fixes": report["fixes"]}

    print(json.dumps(report, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())
